import{_ as a,o as t,c as o,ag as n}from"./chunks/framework.rAhUSuuf.js";const m=JSON.parse('{"title":"Attendance","description":"","frontmatter":{},"headers":[],"relativePath":"attendance.md","filePath":"attendance.md","lastUpdated":null}'),r={name:"attendance.md"};function s(i,e,l,c,d,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="attendance" tabindex="-1">Attendance <a class="header-anchor" href="#attendance" aria-label="Permalink to &quot;Attendance&quot;">​</a></h1><p><em>Last updated: FY 2083/84</em></p><p>It is crucial for you to report to work on time and to avoid unnecessary absences. We understand that you may be absent from work from time to time because of illness or other circumstances beyond your control. However, we will need to take action against anyone who frequently shows up late or frequently becomes absent. When your behavior puts a strain on your coworkers and starts getting noticeable, we will be obliged to terminate your employment.</p><h2 id="how-to-mark-attendance" tabindex="-1">How to mark attendance <a class="header-anchor" href="#how-to-mark-attendance" aria-label="Permalink to &quot;How to mark attendance&quot;">​</a></h2><p>Attendance is managed through <strong>Karyabase</strong>. How you mark attendance depends on your work location:</p><ul><li><strong>Office (default)</strong> — Use the <strong>biometric device</strong> at the office to mark your attendance.</li><li><strong>Remote work</strong> (only with your manager’s approval) <strong>or</strong> when the biometric device is not working — Check in through the <strong>Karyabase</strong> website at <a href="https://karyabase.com" target="_blank" rel="noreferrer">karyabase.com</a>.</li></ul><p>If you fail to mark attendance for a working day and no approved leave (or similar approved absence) exists for that day, the day will default to an <strong>unpaid absent</strong>.</p><h2 id="late-arrivals" tabindex="-1">Late arrivals <a class="header-anchor" href="#late-arrivals" aria-label="Permalink to &quot;Late arrivals&quot;">​</a></h2><p>You are allowed a <strong>weekly cumulative total of 1 hour</strong> of late time. Anything beyond that is deducted automatically by the system on payroll.</p><p>If you will be late, post a message on the <strong>Discord</strong> server to let the team know, and personally notify the <strong>Operations Manager</strong>, a <strong>senior</strong>, or your <strong>manager</strong>. If you expect a longer delay, apply for a <strong>half-day leave</strong> instead.</p><h3 id="excessive-lateness" tabindex="-1">Excessive lateness <a class="header-anchor" href="#excessive-lateness" aria-label="Permalink to &quot;Excessive lateness&quot;">​</a></h3><p>Repeated or excessive lateness will have consequences. You may receive a <strong>warning</strong>, and it will be taken into account in your <strong>performance review</strong>.</p>',12)])])}const g=a(r,[["render",s]]);export{m as __pageData,g as default};
